WITH unpacked AS (SELECT id, plan, currency, tier_limits, tier_prices, discounts, SLICE(tier_limits, 1, 2) AS first_two_limits, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers WHERE currency IN ('USD', 'EUR')) SELECT *, AVG(entry_price) OVER (ORDER BY entry_price, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS entry_price_avg_3, LEAD(avg_tier_price, 1, 0) OVER (PARTITION BY plan ORDER BY entry_price, id) AS next_avg_tier_price, ROW_NUMBER() OVER (ORDER BY entry_price, id) AS row_seq FROM unpacked;
